/**
 * Component: REGISTER - CTA - SECTION animation
 * Author: @abdulbast (https://tailwindflex.com/@abdulbast)
 * Source: https://tailwindflex.com/@abdulbast/register-cta-section-animation
 * Attribution: Créé par @abdulbast sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function RegisterCtaSectionAnimation() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<section class="py-20 dark:bg-black h-[600px]">
  <h2 class="mb-10 text-center text-4xl font-bold uppercase sm:text-5xl md:text-8xl dark:text-white">REGISTER NOW</h2>

  <div class="mx-auto max-w-7xl overflow-hidden rounded-[50px] p-8 sm:p-14 lg:p-20 dark:bg-[#1c1a1a]">
    <h2 class="text-center text-xl leading-loose font-bold sm:text-start md:text-2xl dark:text-white">Early Bird Pricing Ends In:</h2>

    <div class="mx-auto mt-8 w-full sm:w-[700px] lg:w-[900px]">
      <div class="mx-auto flex max-w-md justify-between">
        <span class="min-w-[70px] text-center text-xs font-medium sm:text-sm dark:text-white">DAYS</span>
        <span class="min-w-[70px] text-center text-xs font-medium sm:text-sm dark:text-white">HOURS</span>
        <span class="min-w-[70px] text-center text-xs font-medium sm:text-sm dark:text-white">MINUTES</span>
      </div>

      <div class="countdown-timer relative h-[80px] overflow-hidden sm:h-[220px]">
        <p class="text-center font-mono text-[50px] leading-[1.1] font-normal sm:text-[120px] md:text-[150px] lg:text-[200px] dark:text-white">12:05:3<span class="animated-digit "></span></p>
      </div>
    </div>
  </div>
</section>

<style>
  .countdown-timer {
    animation: typingEffect 2s infinite alternate-reverse;
  }

  @keyframes typingEffect {
    from {
      height: 0;
      opacity: 0;
    }
    to {
      height: 200px;
      opacity: 1;
    }
  }

  .animated-digit::before {
    content: "6";
    animation: digitChange 12s infinite step-end;
  }

  @keyframes digitChange {
    0%, 24.999% { content: "6"; }
    25%, 49.999% { content: "7"; }
    50%, 74.999% { content: "8"; }
    75%, 100% { content: "9"; }
  }
</style>" }} />
  );
}
